import React, { useEffect, useRef, useState } from 'react';
import useCareerStore from '../hooks/useCareerStore';
import { parseResumeText, readResumeFile, RESUME_IMPORT_MAX_BYTES } from '../utils/resumeImport';
import { createResumeTextPdf, resumeTextBlocks } from '../utils/resumeTextPdf';

import { JD_LIMIT, reopenDraft, saveDraft, sourceSnapshot, validDrafts } from '../utils/tailorDrafts';

import AiHandoff from '../components/resume/AiHandoff';
import SummaryProposal from '../components/resume/SummaryProposal';

const field = 'mt-1 block w-full rounded border border-gray-400 bg-white p-2 dark:bg-slate-800';
const button = 'rounded bg-linkedin-700 px-4 py-2 font-medium text-white disabled:opacity-50';


export default function Tailor() {
  const { careerProfile, write } = useCareerStore();
  const [mode, setMode] = useState('profile');
  const [text, setText] = useState('');
  const [loading, setLoading] = useState(false);
  const activeImport = useRef(null);
  useEffect(() => () => activeImport.current?.abort(), []);
  const [job, setJob] = useState({ description: '', company: '', role: '' });
  const [review, setReview] = useState(null);
  const [error, setError] = useState('');

  const [notice, setNotice] = useState('');
  const storedDraftsValid = validDrafts(careerProfile?.tailorDrafts);
  const drafts = storedDraftsValid ? careerProfile?.tailorDrafts ?? [] : [];

  function persist() {
    setError('');
    setNotice('');
    let saved;
    if (write(current => {
      const next = saveDraft(current, review);
      saved = next.tailorDrafts[0];
      return next;
    }, err => setError(err.message || 'Could not save to this browser.'))) {
      setReview(reopenDraft(saved));
      setNotice('Draft saved on this device.');
    }
  }

  function remove(draft) {
    if (!window.confirm('Delete this saved job draft and its source copy?')) return;
    if (write(current => {
      const existing = current.tailorDrafts?.find(item => item.id === draft.id);
      if (existing?.revision !== draft.revision) throw new Error('The draft changed. Reopen it before deleting.');
      return { ...current, tailorDrafts: current.tailorDrafts.filter(item => item.id !== draft.id) };
    }, err => setError(err.message))) setNotice('Draft deleted.');
  }

  async function importFile(file) {
    if (!file) return;
    activeImport.current?.abort();
    const controller = new AbortController();
    activeImport.current = controller;
    setLoading(true);
    setNotice('');
    setError('');
    try {
      let source;
      let notice = '';
      if (/\.pdf$/i.test(file.name)) {
        ({ source, notice } = await (await import('../utils/pdfImport')).readPdfFile(file, controller.signal));
      } else if (/\.docx$/i.test(file.name)) {
        source = await (await import('../utils/docxImport')).readDocxFile(file, controller.signal);
        notice = 'Review the extracted body text below. Check the order of tables and columns, and add any details from headers, footers or text boxes.';
      } else if (/\.txt$/i.test(file.name)) {
        ({ source } = await readResumeFile(file));
      } else {
        throw new Error('Choose a TXT, DOCX or PDF file, or paste your resume text.');
      }
      if (controller.signal.aborted) return;
      setText(source);
      setNotice(notice);
    } catch (err) {
      if (!controller.signal.aborted) setError(err.message);
    } finally {
      if (activeImport.current === controller) {
        activeImport.current = null;
        setLoading(false);
      }
    }
  }

  function prepare(event) {
    event.preventDefault();
    setError('');
    try {
      let source = careerProfile;
      if (mode === 'text') {
        if (new Blob([text]).size > RESUME_IMPORT_MAX_BYTES) throw new Error('Use up to 1 MiB of resume text.');
        const { draft, remaining } = parseResumeText(text);
        source = { ...draft, profile: { ...draft.profile, summary: [draft.profile.summary, remaining].filter(Boolean).join('\n\n') } };
      }
      if (!source || !resumeTextBlocks(source).length) throw new Error('Your profile is empty. Paste a resume or choose a TXT, DOCX or PDF file.');
      if (!job.description.trim() || job.description.length > JD_LIMIT) throw new Error('Enter a job description of up to 30,000 characters.');
      source = sourceSnapshot(source);
      setNotice('');
      setReview({ id: crypto.randomUUID(), revision: 0, source, version: source, job: { ...job } });
    } catch (err) {
      setError(err.message);
    }
  }

  function download() {
    setError('');
    try {
      createResumeTextPdf(review.version).save('Voca-resume.pdf');
    } catch (err) {
      setError(err.message);
    }
  }

  return <main className="mx-auto max-w-3xl space-y-5 p-5 text-gray-900 dark:text-gray-100">
    <h1 className="text-3xl font-bold">Tailor my resume</h1>
    <p>Prepare a resume for one job. Choose Save draft to keep a copy and its job description in this browser.</p>
    {!storedDraftsValid && <p role="alert">Saved drafts could not be read. Restore a backup from the Resume page.</p>}
    {notice && <p role="status">{notice}</p>}
    {!review && drafts.length > 0 && <section className="space-y-2">
      <h2 className="text-xl font-semibold">Saved drafts</h2>
      <ul>{drafts.map(draft => <li className="flex flex-wrap items-center justify-between gap-2 border-b py-2" key={draft.id}>
        <button className="text-left underline" onClick={() => { setReview(reopenDraft(draft)); setNotice(''); setError(''); }}>
          {[draft.job.role, draft.job.company].filter(Boolean).join(' at ') || draft.job.description.slice(0, 70)}
        </button>
        <button onClick={() => remove(draft)}>Delete</button>
      </li>)}</ul>
    </section>}
    {error && <p role="alert" className="rounded border border-red-400 p-3">{error}</p>}
    {!review ? <form onSubmit={prepare} className="space-y-5">
      <fieldset disabled={loading} className="space-y-3">
        <legend className="text-lg font-semibold">Source resume</legend>
        <label className="block"><input type="radio" checked={mode === 'profile'} onChange={() => setMode('profile')} /> Use my Voca profile</label>
        <label className="block"><input type="radio" checked={mode === 'text'} onChange={() => setMode('text')} /> Paste text or open a TXT, DOCX or PDF file</label>
        {mode === 'text' && <>
          <label className="block">Open TXT (1 MiB), DOCX or PDF (5 MiB)<input className={field} type="file" accept=".pdf,application/pdf,.txt,.docx,text/plain,application/vnd.openxmlformats-officedocument.wordprocessingml.document" onChange={e => { const file = e.target.files[0]; e.target.value = ''; importFile(file); }} /></label>
          <label className="block">Resume text<textarea className={field} rows={8} value={text} onChange={e => setText(e.target.value)} /></label>
        </>}
      </fieldset>
      {loading && <button type="button" className="underline" onClick={() => activeImport.current?.abort()}>Cancel import</button>}
      <label className="block">Job description<textarea className={field} rows={6} value={job.description} onChange={e => setJob({ ...job, description: e.target.value })} /></label>
      <div className="grid gap-3 sm:grid-cols-2">
        {['company', 'role'].map(key => <label key={key} className="capitalize">{key} (optional)<input className={field} maxLength={180} value={job[key]} onChange={e => setJob({ ...job, [key]: e.target.value })} /></label>)}
      </div>
      <button className={button} disabled={loading}>Review draft</button>
    </form> : <section className="space-y-4">
      <h2 className="text-xl font-semibold">{[review.job.role, review.job.company].filter(Boolean).join(' at ') || 'Job-specific draft'}</h2>
      <details><summary>Job description</summary><p className="whitespace-pre-wrap">{review.job.description}</p></details>
      <label className="block">Edit draft summary<textarea className={field} rows={5} value={review.version.profile.summary || ''} onChange={e => { setNotice(''); setReview({ ...review, version: { ...review.version, profile: { ...review.version.profile, summary: e.target.value } } }); }} /></label>
      <AiHandoff key={review.id} review={review} onChange={updated => { setNotice(''); setReview(updated); }} />
      <SummaryProposal key={review.id + JSON.stringify(review.proposal)} review={review} onChange={updated => { setNotice(''); setReview(updated); }} />
      <details><summary>Original resume</summary>
        {resumeTextBlocks(review.source).map((block, i) => <p className="whitespace-pre-wrap py-1" key={i}>{block.text}</p>)}
      </details>
      <details open><summary>Resume preview</summary>
        {resumeTextBlocks(review.version).map((block, i) => <p className="whitespace-pre-wrap py-1" key={i}>{block.text}</p>)}
      </details>
      <div className="flex flex-wrap gap-3">
        <button className={button} disabled={!storedDraftsValid} onClick={persist}>Save draft</button>
        <button className={button} onClick={download}>Download draft PDF</button>
        <button className="underline" onClick={() => { setReview(null); setError(''); }}>{review.revision ? 'Back to saved drafts' : 'Discard draft and edit inputs'}</button>
      </div>
    </section>}
  </main>;
}
